[BEGIN]
module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        WL, WR, FL, FR, DL, DR
    } state_t;

    state_t state, next;

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next;
    end

    always_comb begin
        next = state;
        case (state)
            WL: begin
                if (!ground)
                    next = FL;
                else if (dig)
                    next = DL;
                else if (bump_left)
                    next = WR;
                else
                    next = WL;
            end
            WR: begin
                if (!ground)
                    next = FR;
                else if (dig)
                    next = DR;
                else if (bump_right)
                    next = WL;
                else
                    next = WR;
            end
            FL: begin
                if (ground)
                    next = WL;
                else
                    next = FL;
            end
            FR: begin
                if (ground)
                    next = WR;
                else
                    next = FR;
            end
            DL: begin
                if (!ground)
                    next = FL;
                else
                    next = DL;
            end
            DR: begin
                if (!ground)
                    next = FR;
                else
                    next = DR;
            end
            default: next = WL;
        endcase
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

endmodule
[DONE]
